  glossario: [
    ["Anticorpo", "Proteína produzida por linfócitos B que reconhece e neutraliza antígenos."],
    ["Antígeno", "Molécula (geralmente de um agente estranho) que provoca resposta imune."],
    ["Alvéolo", "Pequena bolsa no fim dos bronquíolos onde ocorre a troca de gases."],
    ["Artéria", "Vaso que leva sangue do coração para os tecidos."],
    ["Bile", "Líquido produzido pelo fígado que emulsiona gorduras."],
    ["Capilar", "Vaso microscópico onde ocorrem trocas entre sangue e células."],
    ["Célula", "Menor unidade estrutural e funcional dos seres vivos."],
    ["Enzima", "Proteína que acelera reações químicas, como a digestão."],
    ["Gameta", "Célula reprodutiva haploide (espermatozoide ou ovócito)."],
    ["Hematose", "Troca gasosa nos pulmões: entra O₂ e sai CO₂ do sangue."],
    ["Hormônio", "Mensageiro químico produzido por glândulas e levado pelo sangue."],
    ["Homeostase", "Manutenção do equilíbrio interno do organismo."],
    ["Néfron", "Unidade funcional do rim que filtra o sangue."],
    ["Neurônio", "Célula do sistema nervoso que conduz impulsos."],
    ["Neurotransmissor", "Substância liberada na sinapse que transmite o sinal entre neurônios."],
    ["Peristaltismo", "Contrações em onda que empurram o conteúdo pelo tubo digestório."],
    ["Puberdade", "Período de transformações corporais que leva à maturidade reprodutiva."],
    ["Quimo", "Massa ácida de alimento parcialmente digerido no estômago."],
    ["Sinapse", "Região de comunicação entre um neurônio e outra célula."],
    ["Tecido", "Conjunto de células semelhantes que realizam a mesma função."],
    ["Vacina", "Preparado que estimula a imunidade sem causar a doença."],
    ["Veia", "Vaso que traz sangue dos tecidos de volta ao coração."],
    ["Vilosidade", "Dobra da parede do intestino delgado que amplia a absorção."]
  ],

